export const meta = {
  name: 'markting-ai-audit',
  description: 'Forensic multi-team audit of the repository; specialists write evidence files under docs/audit/agents, leads synthesize team reports',
  phases: [
    { title: 'Specialists', detail: 'one narrow expert per workstream' },
    { title: 'Leads', detail: 'team leads synthesize into docs/audit/*.md' },
  ],
}

const ROOT = '/home/user/markting-ai'
const OUT = `${ROOT}/docs/audit/agents`

const RULES = `
You are one expert in a forensic, evidence-based audit of the repository at ${ROOT} (an Arabic-first "AI media buyer" SaaS built from two vendored Apache-2.0 projects: adport in platform/ and paid-media-agent in engine/, plus glue in services/, infra/, docs/, and the markting modules inside platform/apps/cloud).

NON-NEGOTIABLE RULES
- This is an AUDIT. Do not implement, refactor, fix, or delete anything. The ONLY file you may create or write is your own report: ${OUT}/<YOUR_AGENT_ID>.md (and scratch files under /tmp if you need them). Never touch any other file.
- Repository code is the source of truth. README.md, UPSTREAM.md, docs/*.md, phase reports and any previous summaries are claims to VERIFY, not facts. Where a document and the code disagree, say so.
- Every significant conclusion must carry an evidence citation in the form path:line (relative to ${ROOT}) or a command you actually ran with its exit code, and a classification tag: VERIFIED_CODE, VERIFIED_TEST, VERIFIED_RUNTIME, DOCUMENTED_ONLY, INFERRED, or NOT_VERIFIED. Never upgrade an inference to a fact.
- Severity for defects: P0 (security / data loss / cross-tenant / unsafe ad execution), P1 (production blocker or serious financial risk), P2 (substantial functional or reliability deficiency), P3 (quality / polish / maintainability). Do not inflate. A missing feature is a GAP, not a defect, unless the code claims to provide it.
- Capability classification where applicable: EXISTS_AND_STRONG, EXISTS_BUT_LIMITED, PARTIAL, MOCK_ONLY, DOCUMENTED_NOT_IMPLEMENTED, MISSING, UNSAFE_TO_AUTOMATE.
- Do not label legitimate test fixtures or demo modes as production defects; do flag when demo/mock code can reach production paths.
- You may run read-only commands (rg/grep, cat, sed -n, find, wc, git log) and, where your workstream says so, existing test/typecheck/lint/build commands. Never run anything that writes to an ad platform, never set real credentials, never modify git state. Tooling available: pnpm (run from ${ROOT}/platform), uv (run from ${ROOT}/engine, e.g. "uv run --frozen pytest -q"), node, python3. Docker builds are blocked by the sandbox network; do not retry them.
- Do not read other agents' reports (${OUT}/*.md) unless your workstream explicitly says you are a lead or reviewer.
- Be exhaustive within your scope and skeptical by default. Try to DISPROVE claims. If you cannot verify something, say NOT_VERIFIED and what would be needed.

REPORT FORMAT (write it to ${OUT}/<YOUR_AGENT_ID>.md, then also return the structured JSON):
# <AGENT_ID> — <role>
## Scope inspected (files/dirs, with what you looked for)
## Commands executed (command, exit code, one-line result)
## Findings (one H3 per finding: ID, severity, classification, evidence path:line, description, impact, recommendation)
## Capability assessment (table where applicable: capability | classification | evidence)
## What a world-class system would need (gaps, concrete)
## Disagreements / claims in docs that the code contradicts
## Confidence (0-1) and what was NOT verified
`

const FINDING = {
  type: 'object',
  properties: {
    id: { type: 'string', description: 'e.g. A1-03' },
    title: { type: 'string' },
    severity: { type: 'string', description: 'P0|P1|P2|P3|GAP' },
    classification: { type: 'string', description: 'VERIFIED_CODE|VERIFIED_TEST|VERIFIED_RUNTIME|DOCUMENTED_ONLY|INFERRED|NOT_VERIFIED' },
    evidence: { type: 'array', items: { type: 'string' }, description: 'path:line citations or commands with exit codes' },
    description: { type: 'string' },
    recommendation: { type: 'string' },
  },
  required: ['id', 'title', 'severity', 'classification', 'evidence', 'description', 'recommendation'],
}

const RESULT = {
  type: 'object',
  properties: {
    agent_id: { type: 'string' },
    role: { type: 'string' },
    report_path: { type: 'string' },
    scope: { type: 'string' },
    files_inspected: { type: 'array', items: { type: 'string' } },
    tests_executed: { type: 'array', items: { type: 'string' }, description: 'command => exit code' },
    findings: { type: 'array', items: FINDING },
    capabilities: {
      type: 'array',
      description: 'capability ratings where applicable',
      items: { type: 'object', properties: { capability: { type: 'string' }, provider: { type: 'string' }, rating: { type: 'string' }, evidence: { type: 'string' } }, required: ['capability', 'rating', 'evidence'] },
    },
    key_findings: { type: 'array', items: { type: 'string' }, description: '3-8 one-line takeaways' },
    disagreements: { type: 'string', description: 'where docs/previous summaries or other expected conclusions are contradicted by code' },
    confidence: { type: 'number' },
    not_verified: { type: 'string' },
  },
  required: ['agent_id', 'role', 'report_path', 'scope', 'files_inspected', 'tests_executed', 'findings', 'key_findings', 'disagreements', 'confidence', 'not_verified'],
}

